'use strict';
(()=>{const dialog=document.getElementById('help-dialog'),open=document.getElementById('help-open'),close=document.getElementById('help-close');if(!dialog||!open||!close)return;open.addEventListener('click',()=>{const topic=document.getElementById(document.getElementById('mode').value==='momentum'?'help-momentum':document.getElementById('breakout-profile').value==='candles'?'help-candles':'help-stairs');document.getElementById('help-start').open=true;if(topic)topic.open=true;if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','')});close.addEventListener('click',()=>{if(typeof dialog.close==='function')dialog.close();else dialog.removeAttribute('open');open.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog&&typeof dialog.close==='function')dialog.close()});})();
